const PREFIX='gant02_20261024_';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DAY=86400000, date=s=>new Date(s+'T12:00:00Z'), iso=d=>d.toISOString().slice(0,10), add=(s,n)=>iso(new Date(+date(s)+n*DAY)), diff=(a,b)=>Math.round((date(a)-date(b))/DAY);
const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const label={assigned:'Assigned',in_progress:'In progress',done:'Complete'};
let projects=[],tasks=[],collapsed=new Set(),start=localToday(),days=120,cw=26,pending=0,loading=false,loaded=false,editor=null,editorBaseline='',draggingId=null,draggingKind=null,pointer=null,suppressClick=false;
