let squareDrag=null,deleteMode=false,deleting=false;
const status=(s,failed=false)=>{$('sync').textContent=s;$('sync').classList.toggle('failed',failed);};
function error(e){$('error').textContent=e.message||String(e);$('error').hidden=false;status('Could not sync',true);}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,2600);}
async function api(table,method='GET',body=null,query=''){
 const response=await fetch(API+(table.startsWith('rpc/')?'rpc/'+PREFIX+table.slice(4):PREFIX+table)+query,{method,headers:{apikey:KEY,'Content-Type':'application/json',Prefer:'return=representation,resolution=merge-duplicates'},...(body?{body:JSON.stringify(body)}:{})});
 if(!response.ok){const e=await response.json().catch(()=>({message:response.statusText}));throw Error(e.message||'Database request failed');}return response.status===204?[]:response.json();
}
async function load(quiet=false){if(loading||pending||pointer||squareDrag)return;loading=true;if(!quiet)status('Syncing…');try{const [p,t,c]=await Promise.all([api('projects','GET',null,'?select=*&order=position,created_at'),api('tasks','GET',null,'?select=*&order=position,created_at'),loadCells()]);projects=p;tasks=t;cells=new Map(c.map(x=>[squareKey(x),x]));loaded=true;render();status('All changes saved');$('error').hidden=true;}catch(e){error(e);}finally{loading=false;}}
async function mutate(table,method,body,id){pending++;status('Saving…');try{const result=await api(table,method,body,id?'?id=eq.'+encodeURIComponent(id):'');$('error').hidden=true;return result;}catch(e){error(e);throw e;}finally{pending--;if(!pending&&$('error').hidden)status('All changes saved');}}
async function updateTask(id,patch){const task=tasks.find(t=>t.id===id);if(!task)return;const old={...task};Object.assign(task,patch);render();try{const [saved]=await mutate('tasks','PATCH',patch,id);if(!saved)throw Error('Task was removed. Refresh to continue.');Object.assign(task,saved);render();}catch(e){Object.assign(task,old);render();error(e);}}
function dateHint(day){const n=diff(day,localToday()),weekday=date(day).toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'});return `${n} day${Math.abs(n)===1?'':'s'} out · ${day.slice(5)} ${weekday}`;}
function itemDaysOut(id,kind='task'){const ids=new Set(kind==='project'?tasks.filter(t=>t.project_id===id).map(t=>t.id):[id]);let next=Infinity,recent=-Infinity;for(const cell of cells.values()){if(!cell.status||!(ids.has(cell.task_id)||(kind==='project'&&cell.project_id===id)))continue;const n=diff(cell.day,localToday());if(n>=0)next=Math.min(next,n);else recent=Math.max(recent,n);}return Number.isFinite(next)?String(next):Number.isFinite(recent)?String(recent):'';}
function rowMatches(item,kind='task'){const own=[...cells.values()].filter(c=>(kind==='project'?c.project_id:c.task_id)===item.id&&c.status),statusFilter=$('status-filter').value,horizon=$('days-filter').value,text=kind==='project'?item.name:[item.name,item.assignee,projects.find(p=>p.id===item.project_id)?.name].join(' ');if(q()&&!text.toLowerCase().includes(q()))return false;if(horizon!=='all')return own.some(c=>diff(c.day,localToday())>=0&&diff(c.day,localToday())<=Number(horizon)&&(!statusFilter||c.status===statusFilter));return !statusFilter||(kind==='task'&&item.status===statusFilter)||own.some(c=>c.status===statusFilter);}
function visible(t){return rowMatches(t,'task');}
function q(){return $('search').value.trim().toLowerCase();}
function options(selected){return projects.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('');}
function bands(){let h='';for(let i=0;i<days;i++){const day=add(start,i);if(date(day).getUTCDay()===0)h+=`<span class="weekend-band sunday-band" data-day="${day}" style="left:${i*cw}px;width:${cw}px"></span>`;}return h;}
function spanHTML(s,e,project=false,t=null){if(!s||!e)return '';const x=diff(s,start),n=diff(e,s)+1;if(x+n<=0||x>=days)return '';const left=Math.max(0,x)*cw+2,width=(Math.min(days,x+n)-Math.max(0,x))*cw-4;if(project)return `<span class="project-span" style="left:${left}px;width:${width}px"></span>`;return `<div class="bar ${t.status}" data-id="${t.id}" role="button" tabindex="0" aria-label="${esc(t.name)}, ${s} to ${e}, ${label[t.status]}. Arrow keys move one day; Shift and arrow keys resize." title="${esc(t.name)} · ${s} → ${e}" style="left:${left}px;width:${width}px"><span class="resize left" data-edge="start"></span><span class="bar-label">${esc(t.name)}</span><span class="resize right" data-edge="end"></span></div>`;}
function render(){
 const filter=$('project-filter').value;$('project-filter').innerHTML='<option value="">All projects</option>'+options(filter);
 const dayHeaders=[];for(let i=0;i<days;i++){const d=add(start,i),dt=date(d),month=dt.toLocaleDateString('en-US',{month:'short',timeZone:'UTC'}),weekday=dt.toLocaleDateString('en-US',{weekday:'short',timeZone:'UTC'}).toUpperCase();dayHeaders.push(`<div class="date-column ${d===localToday()?'today':''}" data-day="${d}" title="${dateHint(d)}"><span class="sheet-letter">${columnName(i+2)}</span><span class="header-band"></span><span class="vertical-month">${month}</span><span class="weekday">${weekday}</span><span class="day-number" title="${dateHint(d)}">${String(dt.getUTCDate()).padStart(2,'0')}</span></div>`);}
 const width=days*cw,band=bands();let h=`<div class="grid-header"><div class="frozen"><div class="col-head" aria-hidden="true"></div><div class="col-head"><span class="name-column-letter">A</span>Task / project</div></div><div class="calendar date-columns" style="width:${width}px">${dayHeaders.join('')}</div></div>`;
 let count=0;for(const p of projects.filter(p=>!filter||p.id===filter)){
 const all=tasks.filter(t=>t.project_id===p.id),rows=all.filter(visible);if((q()||$('status-filter').value||$('days-filter').value!=='all')&&!rows.length&&!rowMatches(p,'project'))continue;const dates=all.filter(t=>t.start_date),s=dates.length?dates.map(t=>t.start_date).sort()[0]:null,e=dates.length?dates.map(t=>t.end_date).sort().at(-1):null;
 h+=`<div class="row project-row" data-project="${p.id}"><div class="frozen" draggable="true" data-drag-project="${p.id}"><button class="collapse" data-collapse="${p.id}" aria-label="${collapsed.has(p.id)?'Expand':'Collapse'} project">${collapsed.has(p.id)?'▸':'▾'}</button><button class="project-name" data-open-project="${p.id}" title="${itemDaysOut(p.id,'project')}">${esc(p.name)}</button></div><div class="timeline ${paintMode!==null?'paint-timeline':''}" data-kind="project" data-id="${p.id}" style="width:${width}px">${band}${paintMode!==null?dateSquares(p,'project'):spanHTML(s,e,true)}</div></div>`;
 if(collapsed.has(p.id))continue;
 for(const t of rows){count++;h+=`<div class="row task-row" data-task="${t.id}" data-project="${p.id}"><div class="frozen"><div class="cell row-spacer" aria-hidden="true"></div><div class="cell name-cell" draggable="true" data-drag-task="${t.id}"><span class="task-status dot ${t.status}"></span><button data-open="${t.id}" title="${itemDaysOut(t.id)}">${esc(t.name)}</button>${t.notes?'<span class="note-mark" title="Has notes">≡</span>':''}</div></div><div class="timeline task-timeline paint-timeline" data-kind="task" data-id="${t.id}" style="width:${width}px">${band}${paintMode!==null?dateSquares(t):spanHTML(t.start_date,t.end_date,false,t)}</div></div>`;}
 h+=blankRow('task',p.id,width,band);
 }
 h+=blankRow('project','',width,band);
 if(projects.length&&!count&&!h.includes('class="row project-row"')&&(q()||$('status-filter').value||$('days-filter').value!=='all'))h+='<div class="empty"><h2>No matching tasks</h2><p>Try another search or clear your filters.</p></div>';
 $('grid').innerHTML=h;$('task-count').textContent=`${count} visible tasks`;$('range-label').textContent=date(start).toLocaleDateString('en-US',{month:'short',timeZone:'UTC'});document.documentElement.style.setProperty('--day',cw+'px');
}
function columnName(n){let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26);}return s;}
function blankRow(type,projectId,width,band){const key=type==='project'?'project':projectId;return `<div class="row inline-create-row ${type==='project'?'new-project-row':''}" ${projectId?`data-project="${projectId}"`:''}><div class="frozen"><span class="cell new-row-mark">＋</span><div class="cell"><input class="inline-create" data-create="${type}" data-project-id="${projectId}" data-key="${key}" value="${esc(drafts.get(key)||'')}" aria-label="${type==='project'?'New project name':'New task name in '+projects.find(p=>p.id===projectId)?.name}" placeholder="${type==='project'?'New project…':'New task…'}" title="Type a name, then press Enter or Tab to create" maxlength="200" autocomplete="off" ${creatingRows.has(key)?'disabled':''}></div></div><div class="timeline" style="width:${width}px">${band}</div></div>`;}
async function createInline(input,refocus=false){const {create:type,projectId,key}=input.dataset,name=input.value.trim();if(!name||creatingRows.has(key)||!loaded)return;creatingRows.add(key);input.disabled=true;const table=type==='project'?'projects':'tasks',items=type==='project'?projects:tasks,payload={name,position:Math.max(0,...items.map(x=>x.position))+1024};if(type==='task')payload.project_id=projectId;try{const today=localToday(),[item]=type==='task'?await mutate('rpc/create_task','POST',{p_project_id:projectId,p_name:name,p_position:payload.position,p_day:today}):await mutate(table,'POST',payload);items.push(item);if(type==='task'){const square=squareRow('task',item.id,today,'assigned');cells.set(squareKey(square),square);if(diff(today,start)<0||diff(today,start)>=days){start=today;$('grid-wrap').scrollLeft=0;}}drafts.delete(key);creatingRows.delete(key);if(type==='project')$('project-filter').value='';$('search').value='';$('status-filter').value='';$('days-filter').value='all';render();if(refocus){const next=[...document.querySelectorAll('.inline-create')].find(x=>x.dataset.key===(type==='project'?item.id:key));next?.focus();}}catch{creatingRows.delete(key);input.disabled=false;if(refocus)input.focus();}}
$('grid').addEventListener('input',e=>{if(e.target.matches('.inline-create'))drafts.set(e.target.dataset.key,e.target.value);});
$('grid').addEventListener('focusout',e=>{if(e.target.matches('.inline-create'))createInline(e.target);});
$('grid').addEventListener('keydown',e=>{if(!e.target.matches('.inline-create'))return;if(e.key==='Enter'){e.preventDefault();createInline(e.target,true);}if(e.key==='Escape'){e.target.value='';drafts.delete(e.target.dataset.key);e.target.blur();}});
for(const id of ['project-filter','status-filter','search','days-filter'])$(id).addEventListener(id==='search'?'input':'change',()=>{if(id==='days-filter'&&$('days-filter').value!=='all'){start=localToday();$('grid-wrap').scrollLeft=0;}render();});
$('refresh').onclick=()=>load();$('zoom').onchange=()=>{cw=Number($('zoom').value);render();};$('prev').onclick=()=>{start=add(start,-28);render();};$('next').onclick=()=>{start=add(start,28);render();};$('today').onclick=()=>{start=localToday();$('grid-wrap').scrollLeft=0;render();};
$('grid').addEventListener('click',e=>{if(suppressClick)return;const a=e.target.closest('button');if(a?.dataset.open)deleteMode?deleteItem('tasks',a.dataset.open):openEditor('tasks',a.dataset.open);else if(a?.dataset.openProject)deleteMode?deleteItem('projects',a.dataset.openProject):openEditor('projects',a.dataset.openProject);else if(a?.dataset.collapse){const id=a.dataset.collapse;collapsed.has(id)?collapsed.delete(id):collapsed.add(id);render();}});
function squareKey(row){return (row.project_id?'project/':'task/')+(row.project_id||row.task_id)+'/'+row.day;}
function squareRow(kind,id,day,value){return {[kind==='project'?'project_id':'task_id']:id,day,status:value};}
async function loadCells(){const results=await Promise.all(['cells','project_cells'].map(async table=>{let rows=[],offset=0;while(true){const column=table==='cells'?'task_id':'project_id',page=await api(table,'GET',null,'?select=*&order='+column+',day&limit=1000&offset='+offset);rows.push(...page);if(page.length<1000)return rows;offset+=1000;}}));return results.flat();}
function dayStatus(t,day,kind='task'){return cells.get(kind+'/'+t.id+'/'+day)?.status??null;}
function dateSquares(t,kind='task'){let h='';for(let i=0;i<days;i++){const day=add(start,i),value=dayStatus(t,day,kind);h+=`<button class="date-square ${value||''}" draggable="${!!value}" data-kind="${kind}" data-owner-id="${t.id}" ${kind==='task'?`data-task-id="${t.id}"`:''} data-day="${day}" data-index="${i}" tabindex="${i===0?'0':'-1'}" aria-label="${esc(t.name)}, ${day}: ${label[value]||'Blank'}" title="${diff(day,localToday())}" style="left:${i*cw}px;width:${cw}px"></button>`;}return h;}
function paintPreview(p){const a=Math.min(p.index,p.endIndex??p.index),b=Math.max(p.index,p.endIndex??p.index);for(const square of p.line.querySelectorAll('.date-square')){const selected=Number(square.dataset.index)>=a&&Number(square.dataset.index)<=b;square.classList.toggle('painting',selected);square.style.setProperty('--paint-color',paintMode==='erase'?'#ffffff':({assigned:'#6d8fc3',in_progress:'#d59b38',done:'#4b9b78'}[paintMode]));}}
function paintDates(id,a,b,kind='task'){const value=paintMode==='erase'?null:paintMode,rows=[];for(let i=a;i<=b;i++)rows.push(squareRow(kind,id,add(start,i),value));for(const row of rows)cells.set(squareKey(row),row);render();pending++;status('Saving…');paintQueue=paintQueue.then(async()=>{try{const table=kind==='project'?'project_cells':'cells',column=kind==='project'?'project_id':'task_id';await api(table,'POST',rows,'?on_conflict='+column+',day');if(!paintNeedsReload)$('error').hidden=true;}catch(e){paintNeedsReload=true;error(e);toast('Color could not be saved. Please try again.');}finally{pending--;if(!pending&&paintNeedsReload){try{const saved=await loadCells();cells=new Map(saved.map(x=>[squareKey(x),x]));paintNeedsReload=false;}catch{}}render();if(!pending&&$('error').hidden)status('All changes saved');}});return paintQueue;}
async function moveSquare(source,target){if(source.kind===target.kind&&source.id===target.id&&source.day===target.day)return;const from=squareRow(source.kind,source.id,source.day,null),to=squareRow(target.kind,target.id,target.day,source.value),oldFrom=cells.get(squareKey(from)),oldTo=cells.get(squareKey(to));cells.set(squareKey(from),from);cells.set(squareKey(to),to);pending++;render();status('Saving…');try{await api('rpc/move_cell','POST',{p_source_kind:source.kind,p_source_id:source.id,p_source_day:source.day,p_target_kind:target.kind,p_target_id:target.id,p_target_day:target.day,p_status:source.value});$('error').hidden=true;}catch(e){oldFrom?cells.set(squareKey(from),oldFrom):cells.delete(squareKey(from));oldTo?cells.set(squareKey(to),oldTo):cells.delete(squareKey(to));error(e);}finally{pending--;render();if(!pending&&$('error').hidden)status('All changes saved');}}
$('grid').addEventListener('dragstart',e=>{const square=e.target.closest('.date-square');if(!square)return;const kind=square.dataset.kind,id=square.dataset.ownerId,item=(kind==='project'?projects:tasks).find(x=>x.id===id),value=dayStatus(item,square.dataset.day,kind);if(!value||pending||deleteMode){e.preventDefault();return;}squareDrag={kind,id,day:square.dataset.day,value};pointer=null;e.dataTransfer.setData('text/plain',value);e.dataTransfer.effectAllowed='move';square.classList.add('square-dragging');});
