$('paint-tools').addEventListener('click',e=>{const button=e.target.closest('[data-paint]');if(!button)return;setDeleteMode(false);paintMode=button.dataset.paint;for(const b of $('paint-tools').querySelectorAll('[data-paint]'))b.setAttribute('aria-pressed',String(b===button));render();});
$('grid').addEventListener('keydown',e=>{const square=e.target.closest('.date-square');if(!square||deleteMode)return;const index=Number(square.dataset.index);if(['Enter',' ','Delete','Backspace'].includes(e.key)){e.preventDefault();const previous=paintMode;if(e.key==='Delete'||e.key==='Backspace')paintMode='erase';paintDates(square.dataset.ownerId,index,index,square.dataset.kind);paintMode=previous;document.querySelector(`[data-kind="${square.dataset.kind}"][data-owner-id="${square.dataset.ownerId}"][data-index="${index}"]`)?.focus();}else if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();square.parentElement.querySelector(`[data-index="${index+(e.key==='ArrowRight'?1:-1)}"]`)?.focus();}});
function cellAt(ev,el){return Math.max(0,Math.min(days-1,Math.floor((ev.clientX-el.getBoundingClientRect().left)/cw)));}
$('grid').addEventListener('pointerdown',e=>{if(deleteMode||e.button!==0||(pending&&paintMode===null))return;const line=e.target.closest('.paint-timeline');if(!line)return;const kind=line.dataset.kind||'task',t=(kind==='project'?projects:tasks).find(x=>x.id===line.dataset.id),bar=e.target.closest('.bar'),edge=e.target.dataset.edge,index=cellAt(e,line),colored=paintMode!==null&&paintMode!=='erase'&&dayStatus(t,add(start,index),kind);pointer={id:t.id,kind,line,bar,mode:paintMode!==null?(colored?'square':'paint'):bar?(edge||'move'):'draw',x:e.clientX,y:e.clientY,index,oldStart:t.start_date,oldEnd:t.end_date,moved:false};if(colored)return;line.setPointerCapture(e.pointerId);e.preventDefault();});
$('grid').addEventListener('pointermove',e=>{if(!pointer)return;const p=pointer;if(p.mode==='square')return;if(p.mode==='paint'){p.endIndex=cellAt(e,p.line);paintPreview(p);return;}const delta=Math.round((e.clientX-p.x)/cw);if(Math.abs(e.clientX-p.x)>3||Math.abs(e.clientY-p.y)>3)p.moved=true;let s=p.oldStart,f=p.oldEnd;if(p.mode==='draw'){const i=cellAt(e,p.line);s=add(start,Math.min(p.index,i));f=add(start,Math.max(p.index,i));}else if(p.mode==='move'){s=add(p.oldStart,delta);f=add(p.oldEnd,delta);}else if(p.mode==='start'){s=add(p.oldStart,delta);if(s>f)s=f;}else{f=add(p.oldEnd,delta);if(f<s)f=s;}p.newStart=s;p.newEnd=f;let selection=p.line.querySelector('.selection');if(!selection){selection=document.createElement('div');selection.className='selection';p.line.append(selection);}selection.style.left=Math.max(0,diff(s,start))*cw+'px';selection.style.width=(Math.min(days,diff(f,start)+1)-Math.max(0,diff(s,start)))*cw+'px';selection.title=`${s} → ${f}`;});
async function finishPointer(e){if(!pointer)return;const p=pointer;pointer=null;p.line.querySelector('.selection')?.remove();if(p.line.hasPointerCapture(e.pointerId))p.line.releasePointerCapture(e.pointerId);suppressClick=true;setTimeout(()=>suppressClick=false,100);if(p.mode==='paint'||p.mode==='square'){paintDates(p.id,Math.min(p.index,p.endIndex??p.index),Math.max(p.index,p.endIndex??p.index),p.kind);return;}if(p.mode!=='draw'&&!p.moved){openEditor('tasks',p.id);return;}const s=p.newStart||(p.mode==='draw'?add(start,p.index):p.oldStart),f=p.newEnd||s;if(s!==p.oldStart||f!==p.oldEnd)await updateTask(p.id,{start_date:s,end_date:f});}
