$('grid').addEventListener('keydown',e=>{const bar=e.target.closest('.bar');if(!bar)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();openEditor('tasks',bar.dataset.id);}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const t=tasks.find(t=>t.id===bar.dataset.id),n=e.key==='ArrowRight'?1:-1,patch=e.shiftKey?{end_date:add(t.end_date,n)}:{start_date:add(t.start_date,n),end_date:add(t.end_date,n)};if(!e.shiftKey||patch.end_date>=t.start_date)updateTask(t.id,patch);}});
function clearDrag(){draggingId=null;draggingKind=null;document.querySelectorAll('.drop-target,.drop-before,.drop-after,.dragging').forEach(x=>x.classList.remove('drop-target','drop-before','drop-after','dragging'));}
function insertionPosition(items,targetId,after){const index=items.findIndex(x=>x.id===targetId);if(index<0)return Math.max(0,...items.map(x=>x.position))+1024;const slot=index+(after?1:0),before=items[slot-1]?.position,next=items[slot]?.position;return before===undefined?next-1024:next===undefined?before+1024:(before+next)/2;}
function dropLocation(e){const row=e.target.closest('.row');if(!row)return null;if(draggingKind==='project'){if(row.classList.contains('new-project-row'))return {row,targetId:null,after:true};const projectId=row.dataset.project;if(!projectId)return null;const header=document.querySelector(`.project-row[data-project="${projectId}"]`);return {row:header,targetId:projectId,after:e.clientY>header.getBoundingClientRect().top+header.getBoundingClientRect().height/2};}if(!row.dataset.project)return null;return {row,projectId:row.dataset.project,targetId:row.dataset.task||null,after:!!row.dataset.task&&e.clientY>row.getBoundingClientRect().top+row.getBoundingClientRect().height/2};}
$('grid').addEventListener('dragstart',e=>{if(e.target.closest('.date-square'))return;const source=e.target.closest('[data-drag-task],[data-drag-project]');if(!source||pending||deleteMode||e.target.closest('.collapse')){e.preventDefault();return;}draggingKind=source.dataset.dragProject?'project':'task';draggingId=source.dataset.dragProject||source.dataset.dragTask;e.dataTransfer.setData('text/plain',draggingId);e.dataTransfer.effectAllowed='move';source.closest('.row').classList.add('dragging');});
$('grid').addEventListener('dragover',e=>{if(!draggingId)return;const dest=dropLocation(e);if(!dest||dest.targetId===draggingId)return;e.preventDefault();e.dataTransfer&&(e.dataTransfer.dropEffect='move');document.querySelectorAll('.drop-target,.drop-before,.drop-after').forEach(x=>x.classList.remove('drop-target','drop-before','drop-after'));dest.row.classList.add('drop-target',dest.after?'drop-after':'drop-before');});
$('grid').addEventListener('drop',async e=>{if(!draggingId)return;const dest=dropLocation(e);if(!dest)return;e.preventDefault();const id=draggingId,kind=draggingKind;clearDrag();suppressClick=true;setTimeout(()=>suppressClick=false,250);if(dest.targetId===id)return;
 if(kind==='project'){const item=projects.find(p=>p.id===id);if(!item)return;const old=item.position,siblings=projects.filter(p=>p.id!==id).sort((a,b)=>a.position-b.position),position=insertionPosition(siblings,dest.targetId,dest.after);item.position=position;projects.sort((a,b)=>a.position-b.position);render();try{const [saved]=await mutate('projects','PATCH',{position},id);if(!saved)throw Error('Project was removed. Refresh to continue.');Object.assign(item,saved);}catch(e){item.position=old;projects.sort((a,b)=>a.position-b.position);error(e);}finally{render();}}
 else{const siblings=tasks.filter(t=>t.project_id===dest.projectId&&t.id!==id).sort((a,b)=>a.position-b.position),position=insertionPosition(siblings,dest.targetId,dest.after);collapsed.delete(dest.projectId);await updateTask(id,{project_id:dest.projectId,position});tasks.sort((a,b)=>a.position-b.position);render();}});
$('grid').addEventListener('dragend',()=>{clearDrag();suppressClick=true;setTimeout(()=>suppressClick=false,250);});
function sanitize(html){const doc=new DOMParser().parseFromString(html,'text/html');const allowed=new Set(['P','DIV','BR','B','STRONG','I','EM','U','S','UL','OL','LI','BLOCKQUOTE','H2','H3','A']);for(const el of [...doc.body.querySelectorAll('*')]){if(['SCRIPT','STYLE','IFRAME','OBJECT','SVG','MATH','IMG'].includes(el.tagName)){el.remove();continue;}if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);continue;}const href=el.getAttribute('href');for(const a of [...el.attributes])el.removeAttribute(a.name);if(el.tagName==='A'&&href&&/^https?:\/\//i.test(href)){el.setAttribute('href',href);el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer');}}return doc.body.innerHTML;}
let editorTimer=null,editorSavePromise=null;
function editorState(){return JSON.stringify([$('detail-name').value,$('detail-project').value,$('detail-status').value,$('detail-assignee').value,$('detail-start').value,$('detail-end').value,sanitize($('notes').innerHTML)]);}
async function openEditor(table,id){if(editor&&!await closeEditor())return;const item=(table==='tasks'?tasks:projects).find(x=>x.id===id);if(!item)return;editor={table,id};$('detail-type').textContent=table==='tasks'?'TASK DETAILS':'PROJECT DETAILS';$('detail-name').value=item.name;$('task-fields').hidden=table!=='tasks';$('detail-project').innerHTML=options(item.project_id);$('detail-status').value=item.status||'assigned';$('detail-assignee').value=item.assignee||'';$('detail-start').value=item.start_date||'';$('detail-end').value=item.end_date||'';$('notes').innerHTML=sanitize(item.notes||'');$('detail-message').textContent='Changes save automatically';$('drawer').hidden=$('drawer-shade').hidden=false;editorBaseline=editorState();$('detail-name').focus();}
function queueEditorSave(){if(!editor)return;clearTimeout(editorTimer);$('detail-message').textContent='Unsaved changes…';editorTimer=setTimeout(()=>saveEditor(),500);}
async function saveEditor(){clearTimeout(editorTimer);if(!editor)return true;if(editorSavePromise){const ok=await editorSavePromise;return ok?saveEditor():false;}if(editorState()===editorBaseline){$('detail-message').textContent='Saved automatically';return true;}const current={...editor},snapshot=editorState(),name=$('detail-name').value.trim();if(!name){$('detail-message').textContent='Enter a name to save.';return false;}const patch={name,notes:sanitize($('notes').innerHTML)};if(current.table==='tasks'){const startDate=$('detail-start').value,endDate=$('detail-end').value;if((startDate&&!endDate)||(!startDate&&endDate)||startDate>endDate){$('detail-message').textContent='Choose a valid start and finish.';return false;}Object.assign(patch,{project_id:$('detail-project').value,status:$('detail-status').value,assignee:$('detail-assignee').value,start_date:startDate||null,end_date:endDate||null});}$('detail-message').textContent='Saving…';editorSavePromise=(async()=>{try{const [saved]=await mutate(current.table,'PATCH',patch,current.id);if(!saved)throw Error('This item was removed. Refresh to continue.');const item=(current.table==='tasks'?tasks:projects).find(x=>x.id===current.id);if(item)Object.assign(item,saved);if(editor?.id===current.id&&editor.table===current.table){editorBaseline=snapshot;$('detail-message').textContent='Saved automatically';}render();return true;}catch(e){$('detail-message').textContent='Could not save: '+e.message;return false;}})();const ok=await editorSavePromise;editorSavePromise=null;if(ok&&editor&&editorState()!==editorBaseline)return saveEditor();return ok;}
async function closeEditor(force=false){clearTimeout(editorTimer);if(!force&&editor&&!await saveEditor())return false;editor=null;$('drawer').hidden=$('drawer-shade').hidden=true;return true;}
$('detail-form').addEventListener('input',queueEditorSave);$('detail-form').addEventListener('change',queueEditorSave);
$('detail-form').onsubmit=e=>{e.preventDefault();saveEditor();};
$('close-drawer').onclick=$('drawer-shade').onclick=()=>closeEditor();document.addEventListener('keydown',e=>{if(e.key==='Escape'&&editor)closeEditor();});window.addEventListener('beforeunload',e=>{if(pending||(editor&&editorState()!==editorBaseline)){e.preventDefault();e.returnValue='';}});
$('clear-dates').onclick=()=>{$('detail-start').value=$('detail-end').value='';queueEditorSave();};
document.querySelectorAll('[data-command]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>{$('notes').focus();document.execCommand(b.dataset.command,false);queueEditorSave();};});
$('add-link').onmousedown=e=>e.preventDefault();$('add-link').onclick=()=>{const url=prompt('Link URL (https://…)');if(!url)return;if(!/^https?:\/\//i.test(url)){toast('Use a full https:// or http:// URL');return;}$('notes').focus();document.execCommand('createLink',false,url);queueEditorSave();};
$('notes').addEventListener('paste',e=>{e.preventDefault();const html=e.clipboardData.getData('text/html'),plain=e.clipboardData.getData('text/plain');document.execCommand('insertHTML',false,html?sanitize(html):esc(plain).replace(/\n/g,'<br>'));queueEditorSave();});
function setDeleteMode(active){deleteMode=active;$('trash-mode').setAttribute('aria-pressed',String(active));$('grid').classList.toggle('delete-mode',active);for(const b of $('paint-tools').querySelectorAll('[data-paint]'))b.setAttribute('aria-pressed',String(!active&&b.dataset.paint===paintMode));}
$('trash-mode').onclick=async()=>{if(editor&&!await closeEditor())return;setDeleteMode(!deleteMode);if(deleteMode)toast('Click a project or task name to delete. Escape cancels.');};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&deleteMode)setDeleteMode(false);});
async function deleteItem(table,id){if(deleting)return false;deleting=true;$('trash-mode').disabled=$('delete-item').disabled=true;try{await paintQueue;if(editorSavePromise)await editorSavePromise;if(pending){toast('Wait for changes to finish saving, then try again.');return false;}const item=(table==='projects'?projects:tasks).find(x=>x.id===id);if(!item)return false;const count=tasks.filter(t=>t.project_id===id).length,message=table==='projects'?`Delete project “${item.name}” and all ${count} of its tasks?`:`Delete task “${item.name}”?`;if(!confirm(message))return false;if(editor?.id===id&&editor.table===table)clearTimeout(editorTimer);await mutate(table,'DELETE',null,id);const removedTasks=new Set(table==='projects'?tasks.filter(t=>t.project_id===id).map(t=>t.id):[id]);if(table==='projects'){projects=projects.filter(x=>x.id!==id);tasks=tasks.filter(x=>x.project_id!==id);collapsed.delete(id);drafts.delete(id);}else tasks=tasks.filter(x=>x.id!==id);for(const [key,cell] of cells)if(removedTasks.has(cell.task_id)||(table==='projects'&&cell.project_id===id))cells.delete(key);if(editor?.id===id&&editor.table===table)closeEditor(true);setDeleteMode(false);render();toast(table==='projects'?'Project deleted':'Task deleted');return true;}catch{return false;}finally{deleting=false;$('trash-mode').disabled=$('delete-item').disabled=false;}}
$('delete-item').onclick=()=>{if(editor)deleteItem(editor.table,editor.id);};
load();setInterval(()=>{if(!document.hidden&&!editor&&!document.activeElement?.closest('.grid'))load(true);},15000);
